import numpy as np
import pandas as pd

train = pd.read_csv('train.csv')
test = pd.read_csv('test.csv')
TARGET_COLUMN = 'target'
feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
X_train = train[feature_cols].values.astype(float)
y_train = train[TARGET_COLUMN].values
X_test = test[feature_cols].values.astype(float)
y_test = test[TARGET_COLUMN].values

# QDA
classes = np.unique(y_train)
priors = {}
means = {}
covs = {}
for c in classes:
    mask = y_train == c
    priors[c] = mask.sum() / len(y_train)
    Xc = X_train[mask]
    means[c] = Xc.mean(axis=0)
    cov = np.cov(Xc, rowvar=False)
    reg = 0.1 * np.eye(50)
    covs[c] = cov + reg

correct = 0
for i in range(len(X_test)):
    scores = {}
    for c in classes:
        diff = X_test[i] - means[c]
        try:
            inv_cov = np.linalg.inv(covs[c])
            log_det = np.log(np.linalg.det(covs[c]) + 1e-15)
        except:
            continue
        maha = diff @ inv_cov @ diff
        scores[c] = -0.5 * (maha + log_det) + np.log(priors[c])
    if scores:
        pred = max(scores, key=scores.get)
        if pred == y_test[i]:
            correct += 1
print(f'QDA (reg=0.1): accuracy={correct/len(y_test):.4f}')

# Try different regularization values
for reg in [0.01, 0.05, 0.2, 0.5, 1.0, 2.0, 5.0]:
    covs = {}
    for c in classes:
        mask = y_train == c
        Xc = X_train[mask]
        means[c] = Xc.mean(axis=0)
        cov = np.cov(Xc, rowvar=False)
        covs[c] = cov + reg * np.eye(50)

    correct = 0
    for i in range(len(X_test)):
        scores = {}
        for c in classes:
            diff = X_test[i] - means[c]
            try:
                inv_cov = np.linalg.inv(covs[c])
                log_det = np.log(np.linalg.det(covs[c]) + 1e-15)
            except:
                continue
            maha = diff @ inv_cov @ diff
            scores[c] = -0.5 * (maha + log_det) + np.log(priors[c])
        if scores:
            pred = max(scores, key=scores.get)
            if pred == y_test[i]:
                correct += 1
    print(f'QDA (reg={reg:.2f}): accuracy={correct/len(y_test):.4f}')
"
